const directoryHosts = [
  'designrush.com',
  'clutch.co',
  'sortlist.com',
  'goodfirms.com',
  'goodfirms.co',
  'justdial.com',
  'sulekha.com',
  'indiamart.com',
  'facebook.com',
  'instagram.com',
  'linkedin.com',
  'google.com',
  'yelp.com'
];

function cleanUrl(value) {
  const rawUrl = String(value || '').trim();

  if (!rawUrl) {
    return {
      source_url: null,
      domain: null,
      url_error: 'URL is empty'
    };
  }

  const urlWithProtocol = /^https?:\/\//i.test(rawUrl)
    ? rawUrl
    : `https://${rawUrl}`;

  const match = urlWithProtocol.match(
    /^https?:\/\/([^/?#]+)(\/[^?#]*)?/i
  );

  if (!match) {
    return {
      source_url: null,
      domain: null,
      url_error: 'URL format could not be recognized'
    };
  }

  const domain = match[1]
    .toLowerCase()
    .replace(/^www\./, '');

  const path = (match[2] || '/')
    .replace(/\/+$/, '') || '/';

  return {
    source_url: `https://${domain}${path}`,
    domain,
    url_error: null
  };
}

return items.map((item) => {
  const result = item.json.results || item.json;

  const originalUrl = result.url;
  const cleaned = cleanUrl(originalUrl);

  const isDirectory =
    cleaned.domain &&
    directoryHosts.some((host) =>
      cleaned.domain === host ||
      cleaned.domain.endsWith(`.${host}`)
    );

  return {
    json: {
      query: item.json.query || null,
      title: result.title || null,
      content: result.content || null,
      score: result.score || null,
      url: originalUrl || null,
      source_url: cleaned.source_url,
      domain: cleaned.domain,
      url_error: cleaned.url_error,
      candidate_type: isDirectory
        ? 'directory_or_platform'
        : 'potential_company',
      data_quality_status:
        cleaned.source_url && cleaned.domain
          ? 'valid_url'
          : 'invalid_url'
    }
  };
});

const rawText = String($json.website_text || '');

const cleanedText = rawText
  // Convert [tel:+919...] to +919...
  .replace(/\[(?:tel:)([^\]]+)\]/gi, ' $1 ')

  // Convert [mailto:email@example.com] to email@example.com
  .replace(/\[(?:mailto:)([^\]]+)\]/gi, ' $1 ')

  // Remove bracketed full URLs
  .replace(/\[https?:\/\/[^\]]+\]/gi, ' ')

  // Remove normal full URLs, including social-media URLs
  .replace(/https?:\/\/[^\s\]]+/gi, ' ')

  // Remove image and asset paths
  .replace(
    /\[?\/?(?:images|icons|assets|static)\/[^\]\s]+/gi,
    ' '
  )

  // Remove relative webpage links such as [seo-company.html]
  .replace(
    /\[\/?[^\]]+\.(?:html?|php|aspx?)(?:\?[^\]]*)?\]/gi,
    ' '
  )

  // Remove menu artifacts
  .replace(/\/Menu/gi, ' ')

  // Remove remaining square brackets but keep their text
  .replace(/\[([^\]]+)\]/g, ' $1 ')

  // Replace stray slash characters with spaces
  .replace(/\//g, ' ')

  // Normalize repeated spaces
  .replace(/\s+/g, ' ')

  .trim();

const maximumCharacters = 12000;

const shortenedText = cleanedText.slice(0, maximumCharacters);

const {
  website_html,
  website_text,
  ...otherFields
} = $json;

return {
  json: {
    ...otherFields,
    clean_website_text: shortenedText,
    text_character_count: cleanedText.length,
    text_quality: cleanedText.length >= 300
      ? 'usable'
      : 'short'
  }
};

// Get current ScrapeGraphAI item payload
const itemJson = $input.item.json || {};
const extracted = itemJson.json || itemJson;
const itemIndex = $input.item.index;

// Safely pull all items from upstream nodes
let originalItems = [];
try {
  originalItems = $('Keep Valid Company Websites').all();
} catch (e) {
  originalItems = [];
}

let normalizedUrlItems = [];
try {
  normalizedUrlItems = $('Normalize Company URLs').all();
} catch (e) {
  normalizedUrlItems = [];
}

// 1. Try finding target URL from ScrapeGraphAI payload or error metadata
const targetUrl = extracted.url || 
                  itemJson.url || 
                  $input.item.json?.error?.config?.url || 
                  $input.item.json?.metadata?.url || '';

// 2. Look up original item: match by URL first, fallback to item index array mapping
let original = {};
if (targetUrl) {
  original = originalItems.find(i => 
    (i.json.source_url && targetUrl.includes(i.json.source_url)) ||
    (i.json.domain && targetUrl.includes(i.json.domain))
  )?.json || {};
}

// If URL matching didn't yield a match, retrieve by index from originalItems
if (!original.source_url && originalItems[itemIndex]) {
  original = originalItems[itemIndex].json || {};
}

let normalizedUrlData = {};
if (targetUrl) {
  normalizedUrlData = normalizedUrlItems.find(i => 
    (i.json.source_url && targetUrl.includes(i.json.source_url)) ||
    (i.json.domain && targetUrl.includes(i.json.domain))
  )?.json || {};
}
if (!normalizedUrlData.source_url && normalizedUrlItems[itemIndex]) {
  normalizedUrlData = normalizedUrlItems[itemIndex].json || {};
}

// Extract arrays safely
const services = Array.isArray(extracted.services) ? extracted.services : [];
const publicEmails = Array.isArray(extracted.public_emails) ? extracted.public_emails : [];
const publicPhoneNumbers = Array.isArray(extracted.public_phone_numbers) ? extracted.public_phone_numbers : [];

// Clean website text
const cleanWebsiteText = extracted.clean_website_text || original.clean_website_text || '';

return {
  json: {
    query: original.query || null,
    title: original.title || null,
    source_url: original.source_url || normalizedUrlData.source_url || targetUrl || null,
    domain: original.domain || normalizedUrlData.domain || null,
    candidate_type: original.candidate_type || 'potential_company',
    search_score: original.score || null,
    company_description: extracted.company_description || null,
    services: services,
    location_evidence: extracted.location_evidence || null,
    public_emails: publicEmails,
    public_phone_numbers: publicPhoneNumbers,
    clean_website_text: cleanWebsiteText,
    extraction_method: 'scrapegraphai',
    extraction_status: (extracted.company_description && services.length > 0) ? 'success' : 'partial',
    text_character_count: cleanWebsiteText.length,
    text_quality: cleanWebsiteText.length >= 300 ? 'usable' : 'short',
    scrapegraph_usage: itemJson.usage || extracted.usage || null
  }
};

const aiResult = $json.output || $json;

const mergedCompany =
  $('Merge Company Records').item.json;

const normalizedCompany =
  $('Normalize Company URLs').item.json;

function valueOrNull(firstValue, secondValue) {
  return firstValue ?? secondValue ?? null;
}

// Read and safely limit the AI score between 0 and 100
const rawLeadScore = Number(aiResult.lead_score);

let leadScore = Number.isFinite(rawLeadScore)
  ? rawLeadScore
  : 0;

// Convert decimal score such as 0.95 into 95
if (leadScore >= 0 && leadScore <= 1) {
  leadScore = leadScore * 100;
}

// Keep the final lead score as a whole number from 0 to 100
leadScore = Math.round(
  Math.max(0, Math.min(100, leadScore))
);

// Read the minimum score from the original request
const configuredMinimumScore = Number(
  mergedCompany.minimum_score
);

const minimumScore = Number.isFinite(configuredMinimumScore)
  ? Math.max(0, Math.min(100, configuredMinimumScore))
  : 60;

// Assign the lead level using fixed business rules
const leadLevel =
  leadScore >= 80
    ? 'High'
    : leadScore >= 60
      ? 'Medium'
      : 'Low';

// Decide qualification using the minimum score
const qualificationStatus =
  leadScore >= minimumScore
    ? 'Qualified'
    : 'Not Qualified';

return {
  json: {
    // Original search information
    query: valueOrNull(
      mergedCompany.query,
      normalizedCompany.query
    ),

    title: valueOrNull(
      mergedCompany.title,
      normalizedCompany.title
    ),

    url: valueOrNull(
      mergedCompany.url,
      normalizedCompany.url
    ),

    source_url: valueOrNull(
      mergedCompany.source_url,
      normalizedCompany.source_url
    ),

    domain: valueOrNull(
      mergedCompany.domain,
      normalizedCompany.domain
    ),

    candidate_type: valueOrNull(
      mergedCompany.candidate_type,
      normalizedCompany.candidate_type
    ),

    search_score: valueOrNull(
      mergedCompany.search_score,
      normalizedCompany.score
    ),

    // Original research request settings
    niche: mergedCompany.niche || null,

    location: mergedCompany.location || null,

    minimum_score: minimumScore,

    // Company information
    company_name:
      aiResult.company_name ||
      mergedCompany.title ||
      normalizedCompany.title ||
      null,

    company_description:
      aiResult.company_description ||
      mergedCompany.company_description ||
      null,

    services:
      aiResult.services ||
      mergedCompany.services ||
      [],

    location_evidence:
      aiResult.location_evidence ||
      mergedCompany.location_evidence ||
      null,

    clean_website_text:
      aiResult.clean_website_text ||
      mergedCompany.clean_website_text ||
      null,

    // Contact information
    public_emails:
      aiResult.public_emails ||
      mergedCompany.public_emails ||
      [],

    public_phone_numbers:
      aiResult.public_phone_numbers ||
      mergedCompany.public_phone_numbers ||
      [],

    // AI scoring
    industry_fit_score:
      Number(aiResult.industry_fit_score) || 0,

    location_fit_score:
      Number(aiResult.location_fit_score) || 0,

    service_fit_score:
      Number(aiResult.service_fit_score) || 0,

    business_evidence_score:
      Number(aiResult.business_evidence_score) || 0,

    contactability_score:
      Number(aiResult.contactability_score) || 0,

    // Final controlled score
    lead_score: leadScore,

    lead_level: leadLevel,

    qualification_status: qualificationStatus,

    // AI explanation
    reasoning:
      aiResult.reasoning || '',

    recommended_action:
      aiResult.recommended_action || '',

    // Tracking information
    extraction_method:
  mergedCompany.extraction_method || 'http_request_html',

    extraction_status:
      mergedCompany.extraction_status || null,

    processed_at: new Date().toISOString()
  }
};

