const leads = items.map(item => item.json);

const totalLeads = leads.length;

const qualifiedLeads = leads.filter(
  lead => lead.qualification_status === 'Qualified'
);

const highLeads = leads.filter(
  lead => lead.lead_level === 'High'
);

const mediumLeads = leads.filter(
  lead => lead.lead_level === 'Medium'
);

const lowLeads = leads.filter(
  lead => lead.lead_level === 'Low'
);

const averageScore = totalLeads > 0
  ? Math.round(
      leads.reduce(
        (total, lead) => total + Number(lead.lead_score || 0),
        0
      ) / totalLeads
    )
  : 0;

function formatContacts(lead) {
  const emails = Array.isArray(lead.public_emails)
    ? lead.public_emails.join(', ')
    : '';

  const phones = Array.isArray(lead.public_phone_numbers)
    ? lead.public_phone_numbers.join(', ')
    : '';

  if (!emails && !phones) {
    return 'No public contact details found';
  }

  return [
    emails ? `Email: ${emails}` : '',
    phones ? `Phone: ${phones}` : ''
  ]
    .filter(Boolean)
    .join(' | ');
}

function formatLead(lead) {
  return `### ${lead.company_name || 'Unknown company'}

- Lead score: ${lead.lead_score}/100
- Lead level: ${lead.lead_level}
- Qualification: ${lead.qualification_status}
- Domain: ${lead.domain || 'Not available'}
- Website: ${lead.source_url || 'Not available'}
- Contact: ${formatContacts(lead)}
- Reasoning: ${lead.reasoning || 'No reasoning available'}
- Recommended action: ${lead.recommended_action || 'No action provided'}
`;
}

const highPrioritySection = highLeads.length > 0
  ? highLeads.map(formatLead).join('\n')
  : 'No high-priority leads found.';

const mediumPrioritySection = mediumLeads.length > 0
  ? mediumLeads.map(formatLead).join('\n')
  : 'No medium-priority leads found.';

const lowPrioritySection = lowLeads.length > 0
  ? lowLeads.map(formatLead).join('\n')
  : 'No low-priority leads found.';

const reportMarkdown = `# AI Lead Intelligence Report

## Research Summary

- Research query: ${leads[0]?.query || 'Not available'}
- Total companies researched: ${totalLeads}
- Qualified leads: ${qualifiedLeads.length}
- High-priority leads: ${highLeads.length}
- Medium-priority leads: ${mediumLeads.length}
- Low-priority leads: ${lowLeads.length}
- Average lead score: ${averageScore}/100
- Report generated: ${new Date().toISOString()}

## High-Priority Leads

${highPrioritySection}

## Medium-Priority Leads

${mediumPrioritySection}

## Low-Priority Leads

${lowPrioritySection}

## Business Recommendation

Prioritize the high-priority leads first. Review medium-priority leads after verifying their business needs and contact information. Low-priority leads should remain in the CRM for future research but should not receive immediate sales attention.
`;

return [
  {
    json: {
      report_type: 'lead_intelligence_report',
      report_generated_at: new Date().toISOString(),
      total_leads: totalLeads,
      qualified_leads: qualifiedLeads.length,
      high_priority_leads: highLeads.length,
      medium_priority_leads: mediumLeads.length,
      low_priority_leads: lowLeads.length,
      average_score: averageScore,
      report_markdown: reportMarkdown
    }
  }
];
